import type { SceneMood } from "@/video/types";

/**
 * Bundled background-music pack (roadmap A3). Twenty tracks generated by
 * scripts/generate-music.mjs: original compositions, CC0 / public domain (see
 * public/music and docs/LICENSING.md). Served from /public, so the URLs work in
 * the editor preview and the renderer.
 *
 * Every track loops seamlessly over 16 seconds and holds a whole number of
 * beats, so `bpm` and `offsetSeconds` are exact, not estimated: scene cuts can
 * snap to them.
 */

export type MusicEnergy = "low" | "medium" | "high";
export type MusicTag =
  | "upbeat"
  | "calm"
  | "tech"
  | "cinematic"
  | "lo-fi"
  | "corporate"
  | "playful"
  | "dramatic"
  | "acoustic"
  | "ambient";

export interface MusicTrack {
  id: string;
  name: string;
  url: string;
  description: string;
  /** Moods this track fits, used to auto-suggest a track from a scene's `mood`/`musicMood`. */
  moods: SceneMood[];
  /** What the track sounds like, for picking by theme or by hand. */
  tags: MusicTag[];
  energy: MusicEnergy;
  /** Beats per minute of the main pulse. */
  bpm: number;
  /** Seconds from the start of the loop to the first beat. */
  offsetSeconds: number;
  /** Seconds the track loops over. */
  loopSeconds: number;
}

const LOOP = 16;

const track = (
  id: string,
  name: string,
  description: string,
  moods: SceneMood[],
  tags: MusicTag[],
  energy: MusicEnergy,
  bpm: number,
): MusicTrack => ({
  id,
  name,
  url: `/music/${id}.wav`,
  description,
  moods,
  tags,
  energy,
  bpm,
  offsetSeconds: 0,
  loopSeconds: LOOP,
});

