/** Pick the bundled track that best matches a scene mood, if any. */
export function suggestBundledTrack(
  mood: string | undefined,
): MusicTrack | undefined {
  if (!mood) return undefined;
  return MUSIC_LIBRARY.find((t) => t.moods.includes(mood as SceneMood));
}

/** Words in a theme's `musicMood` or a person's search that point at a tag. */
const TAG_WORDS: Record<MusicTag, string[]> = {
  upbeat: [
    "upbeat",
    "pop",
    "energetic",
    "happy",
    "bright",
    "fast",
    "uplifting",
  ],
  calm: ["calm", "gentle", "light", "soft", "relax", "warm", "peaceful"],
  tech: ["tech", "electronic", "synthwave", "focused", "digital", "software"],
  cinematic: ["cinematic", "epic", "trailer", "film", "score"],
  "lo-fi": ["lofi", "lo-fi", "chill", "study"],
  corporate: ["corporate", "business", "professional", "uplifting"],
  playful: ["playful", "ukulele", "fun", "quirky", "bounce"],
  dramatic: ["dramatic", "tense", "tension", "intense", "stakes"],
  acoustic: ["acoustic", "piano", "guitar", "fingerstyle", "organic"],
  ambient: ["ambient", "pad", "atmospheric", "minimal"],
};

/**
 * Choose a bundled track for a text such as a theme's music mood ("upbeat pop",
 * "corporate uplifting"). Scores each track by how many of its tags the words
 * point at; ties go to the earlier track, so the answer never changes.
 */
export function suggestTrackForText(
  text: string | undefined,
  tracks: readonly MusicTrack[] = MUSIC_LIBRARY,
): MusicTrack | undefined {
  if (!text) return undefined;
  const words = text.toLowerCase();
  let best: { track: MusicTrack; score: number } | undefined;
  for (const candidate of tracks) {
    const score = candidate.tags.reduce(
      (sum, tag) =>
        sum + (TAG_WORDS[tag].some((word) => words.includes(word)) ? 1 : 0),
      0,
    );
    if (score > 0 && (!best || score > best.score))
      best = { track: candidate, score };
  }
  return best?.track;
}

/** Beat times (seconds) of a track over `seconds`, looping. */
export function trackBeatTimes(track: MusicTrack, seconds: number): number[] {
  const interval = 60 / track.bpm;
  const out: number[] = [];
  for (let loop = 0; loop < seconds; loop += track.loopSeconds) {
    for (let t = track.offsetSeconds; t < track.loopSeconds; t += interval) {
      const at = loop + t;
      if (at >= seconds) return out;
      out.push(Math.round(at * 1000) / 1000);
    }
  }
  return out;
}

/**
 * The nearest beat to `seconds`, if one is within `toleranceSeconds`; otherwise
 * the time is returned unchanged. Cuts only move toward a beat when it is close.
 */
export function snapToBeat(
  seconds: number,
  track: MusicTrack,
  toleranceSeconds = 0.25,
): number {
  const interval = 60 / track.bpm;
  const beats = Math.round((seconds - track.offsetSeconds) / interval);
  const nearest = track.offsetSeconds + beats * interval;
  return Math.abs(nearest - seconds) <= toleranceSeconds
    ? Math.round(nearest * 1000) / 1000
    : seconds;
}
